import { memo, useCallback, useEffect, useMemo, useRef, useState } from 'react'

import { useAtomValue } from 'jotai'

import HearingIcon from '@mui/icons-material/Hearing'
import VisibilityIcon from '@mui/icons-material/Visibility'
import {
  Alert,
  Box,
  Button,
  IconButton,
  LinearProgress,
  TextareaAutosize,
  Typography,
} from '@mui/material'
import { styled } from '@mui/material/styles'

import { useIsMobile } from '@/hooks/useIsMobile'
import { useTypedSearchParams } from '@/hooks/useTypedSearchParams'
import { routes } from '@/routes'

import { learnConfigAtom } from '../atoms'
import { useFlashCardQuiz } from '../hooks/useFlashCardQuiz'
import { useTts } from '../lib/tts'

import DrawPadLayout from './DrawPadLayout'
import { QuizContainer, QuizSuspenseWrapper } from './QuizLayout'
import { Question } from './RenderContext'

export type ShortAnswerViewProps = {
  className?: string
}

function cleanUpString(s: string) {
  return s
    .toLowerCase()
    .replace(/<br\/?>/g, '')
    .replace(/[-—!"'""'<>:\\.\\,?\s]/g, '')
}

function compareAnswer(source: string, target: string) {
  const s = cleanUpString(source)
  const t = cleanUpString(target)
  // console.log('compareAnswer', s, t)
  return s === t
}

const TextDiff = styled('div')(({ theme: { palette } }) => ({
  fontSize: '1.2rem',
  lineHeight: '1.8rem',
  wordBreak: 'break-word',
  '& span': {
    color: palette.mode === 'dark' ? palette.success.light : palette.success.main,
    fontWeight: 'bold',
  },
  '& del': {
    opacity: 0,
    textDecoration: 'none',
  },
  '& ins': {
    color: palette.mode === 'dark' ? palette.warning.light : palette.warning.main,
    fontWeight: 'bold',
  },
  '&.showAnswer': {
    '& span': {
      color: palette.mode === 'dark' ? palette.success.light : palette.success.main,
      fontWeight: 'bold',
    },
    '& del': {
      color: palette.mode === 'dark' ? palette.error.light : palette.error.main,
      opacity: 1,
      fontWeight: 'bold',
      textDecoration: 'line-through',
    },
    '& ins': {
      color: palette.mode === 'dark' ? palette.warning.light : palette.warning.main,
      fontWeight: 'bold',
    },
  },
}))

const StyledTextarea = styled(TextareaAutosize)(({ theme: { palette } }) => ({
  fontSize: '1rem',
  padding: '.5rem',
  backgroundColor: palette.background.paper,
  color: palette.text.primary,
  border: `1px solid ${palette.divider}`,
  borderRadius: '4px',
  outline: 'none',
  '&:focus': {
    borderColor: palette.primary.main,
  },
}))

function ShortAnswerViewContent(props: ShortAnswerViewProps) {
  const { className } = props
  const { queryParams } = useTypedSearchParams(routes.flashMan.learn.shortAnswer.$config)
  const { owner, repo, path } = queryParams

  const quizState = useFlashCardQuiz({ owner, repo, path })
  const { content, currentIndex, currentItem, isComplete, recordResult, advance, restart } =
    quizState

  // identity를 고정해 memo(DrawPadLayout/DrawPad) 및 하위 힌트 Dialog의
  // 불필요한 리렌더링을 막는다.
  const contentSha = content?.sha
  const noteTarget = useMemo(
    () =>
      owner && repo && path && contentSha && currentItem
        ? {
            owner,
            repo,
            path,
            sha: contentSha,
            lineNo: currentItem.lineNo,
            itemId: currentItem.itemId,
          }
        : null,
    [owner, repo, path, contentSha, currentItem]
  )

  const { isMobile } = useIsMobile()
  const { ttsForQuestion, ttsLang } = useAtomValue(learnConfigAtom)
  const playTts = useTts(ttsLang)

  const [answer, setAnswer] = useState('')
  const [correct, setCorrect] = useState<boolean | undefined>(undefined)
  const [showAnswer, setShowAnswer] = useState(false)
  const [checking, setChecking] = useState(false)
  const refShowAnswer = useRef(false)
  const refTextArea = useRef<HTMLTextAreaElement>(null)

  useEffect(() => {
    if (showAnswer) {
      refShowAnswer.current = true
    }
  }, [showAnswer])

  const handleResult = useCallback(
    (result: 'pass' | 'fail') => {
      recordResult(result)
      setCorrect(result === 'pass')

      setTimeout(() => {
        setShowAnswer(false)
        setCorrect(undefined)
        setAnswer('')
        setChecking(false)
        refShowAnswer.current = false
        advance()
        refTextArea.current?.focus()
      }, 1000)
    },
    [recordResult, advance]
  )

  // Handle text input
  const handleAnswer = useCallback(
    (e: React.ChangeEvent<HTMLTextAreaElement>) => {
      const value = e.target.value
      setAnswer(value)
      setShowAnswer(false)
      if (currentItem && compareAnswer(currentItem.a, value)) {
        handleResult(refShowAnswer.current ? 'fail' : 'pass')
      }
    },
    [currentItem, handleResult]
  )

  // Keyboard shortcuts
  const handleKeyDown = useCallback((e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === 'Enter') {
      setChecking((prev) => !prev)
      e.preventDefault()
      e.stopPropagation()
    }
    if (e.key === '?') {
      setShowAnswer((prev) => !prev)
      e.preventDefault()
      e.stopPropagation()
    }
  }, [])

  // text-diff는 구식 CJS 패키지라 동적 import로 로드한다(short-answer 진입 시에만 필요).
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const [diff, setDiff] = useState<any>(null)

  useEffect(() => {
    import('text-diff').then((module) => {
      setDiff(new (module.default || module)())
    })
  }, [])

  // Compute diff
  const { diffHtml, ratio } = useMemo(() => {
    if (!currentItem || !diff) return { diffHtml: '', ratio: 0 }
    const target = currentItem.a.replaceAll('<br/>', '\n').toLowerCase()
    const textDiff: [match: number, str: string][] = diff.main(target, answer.toLowerCase())
    const ratio =
      (100 * textDiff.filter(([match]) => match === 0).reduce((ret, [, s]) => ret + s.length, 0)) /
      target.length
    const diffHtml = diff.prettyHtml(textDiff)
    return { ratio, diffHtml }
  }, [currentItem, diff, answer])

  // Auto-play TTS and focus textarea on question change
  useEffect(() => {
    if (ttsForQuestion && currentItem && !isComplete) {
      playTts(currentItem.q)
    }
    refTextArea.current?.focus()
  }, [currentIndex, currentItem, ttsForQuestion, playTts, isComplete])

  const handleRestart = useCallback(() => {
    restart()
    setAnswer('')
    setCorrect(undefined)
    setShowAnswer(false)
    setChecking(false)
    refShowAnswer.current = false
  }, [restart])

  return (
    <QuizContainer
      className={'ShortAnswerView ' + (className || '')}
      queryParams={queryParams}
      quizState={quizState}
      onRestart={handleRestart}
    >
      {/* Question & Diff area */}
      <DrawPadLayout
        sx={{ flexGrow: 1 }}
        question={currentItem?.q || ''}
        answer={currentItem?.a || ''}
        clearKey={currentIndex}
        noteTarget={noteTarget}
      >
        <Question text={currentItem?.q || ''} />

        <div>
          {correct === undefined && (showAnswer || checking) && (
            <TextDiff
              className={showAnswer ? 'showAnswer' : undefined}
              dangerouslySetInnerHTML={{ __html: diffHtml }}
            />
          )}
          {correct !== undefined && (
            <TextDiff className="showAnswer" dangerouslySetInnerHTML={{ __html: diffHtml }} />
          )}
          {correct === true && (
            <Box sx={{ mt: 1 }}>
              <Alert>정답입니다.</Alert>
            </Box>
          )}
          {correct === false && (
            <Box sx={{ mt: 1 }}>
              <Alert severity="error">다음에 도전해 주세요.</Alert>
            </Box>
          )}
        </div>
      </DrawPadLayout>

      {/* Input area */}
      <Box
        sx={{
          position: 'sticky',
          bottom: 0,
          display: 'flex',
          flexDirection: 'column',
          gap: 1,
        }}
      >
        <Box sx={{ display: 'flex', alignItems: 'center' }}>
          <Button onClick={() => handleResult('fail')}>몰라요</Button>
          <Box sx={{ flexGrow: 1, display: 'flex', alignItems: 'center', px: 1 }}>
            <LinearProgress sx={{ width: '100%' }} variant="determinate" value={ratio} />
          </Box>
          <Button disabled={ratio < 80} onClick={() => handleResult('pass')}>
            성공
          </Button>
          {ttsForQuestion && (
            <IconButton
              onClick={() => {
                if (currentItem) playTts(currentItem.q)
              }}
            >
              <HearingIcon />
            </IconButton>
          )}
          <IconButton
            color="secondary"
            disabled={showAnswer}
            onClick={() => {
              setShowAnswer(true)
              refTextArea.current?.focus()
            }}
          >
            <VisibilityIcon />
          </IconButton>
        </Box>
        <StyledTextarea
          ref={refTextArea}
          aria-label="answer input"
          minRows={3}
          maxRows={7}
          placeholder="답을 입력해 주세요"
          value={answer}
          onChange={handleAnswer}
          onKeyDown={handleKeyDown}
        />

        {/* Keyboard hints */}
        {!isMobile && (
          <Typography variant="caption" color="text.secondary" sx={{ textAlign: 'center' }}>
            Enter: 확인 | ?: 정답 보기
          </Typography>
        )}
      </Box>
    </QuizContainer>
  )
}

function ShortAnswerView(props: ShortAnswerViewProps) {
  return (
    <QuizSuspenseWrapper>
      <ShortAnswerViewContent {...props} />
    </QuizSuspenseWrapper>
  )
}

export default memo(ShortAnswerView)
